"""Policy language: tokenizer, recursive-descent parser and declared per-string bounds.

The language is 'PREDICATE ACTION;' rules over sequences of registered services.
Whitespace between tokens is limited to space, tab, form feed, CR and LF.
Parse failures and declared-bound violations both raise PolicyError, which makes
the string invalid (uncounted for whole-request totals, and its stage rejects).
"""


class PolicyError(ValueError):
    pass


_WS = frozenset(' \t\x0c\r\n')
_ATOM_KINDS = frozenset(('match', 'startswith', 'endswith', 'contains'))


def tokenize(text):
    """Lex policy text into tokens: '(', ')', ',', ';' or 'k:NAME'."""
    toks = []
    append = toks.append
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in _WS:
            i += 1
            continue
        if ch in '(),;':
            append(ch)
            i += 1
            continue
        if 'A' <= ch <= 'Z' or 'a' <= ch <= 'z':
            j = i + 1
            while j < n:
                c = text[j]
                if 'A' <= c <= 'Z' or 'a' <= c <= 'z' or '0' <= c <= '9':
                    j += 1
                else:
                    break
            if j - i > 24:
                raise PolicyError('name')
            append('k:' + text[i:j])
            i = j
            continue
        raise PolicyError('char')
    return toks


def _parse(toks):
    """Parse tokens into a list of (predicate, action) rules.

    Predicate nodes: ('and',l,r) ('or',l,r) ('not',p)
                     ('match',path) ('startswith',path)
                     ('endswith',path) ('contains',path) with path a name tuple.
    """
    pos = 0
    n = len(toks)

    def peek():
        return toks[pos] if pos < n else None

    def advance():
        nonlocal pos
        if pos >= n:
            raise PolicyError('eof')
        t = toks[pos]
        pos += 1
        return t

    def parse_path():
        t = peek()
        if t == ')':
            return ()
        names = []
        while True:
            t = advance()
            if not (isinstance(t, str) and t.startswith('k:')):
                raise PolicyError('path')
            names.append(t[2:])
            if len(names) > 16:
                raise PolicyError('pathlen')
            t = peek()
            if t == ',':
                pos += 1
                continue
            return tuple(names)

    def parse_pred(depth):
        # depth is the nesting level of this node; an atom has depth 1.
        if depth > 16:
            raise PolicyError('depth')
        t = advance()
        if t == '(':
            left = parse_pred(depth + 1)
            op = advance()
            if op == 'k:and':
                kind = 'and'
            elif op == 'k:or':
                kind = 'or'
            else:
                raise PolicyError('op')
            right = parse_pred(depth + 1)
            if advance() != ')':
                raise PolicyError('paren')
            return (kind, left, right)
        if isinstance(t, str) and t.startswith('k:'):
            word = t[2:]
            if word == 'not':
                if advance() != '(':
                    raise PolicyError('not')
                sub = parse_pred(depth + 1)
                if advance() != ')':
                    raise PolicyError('paren')
                return ('not', sub)
            if word in _ATOM_KINDS:
                if advance() != '(':
                    raise PolicyError('atom')
                path = parse_path()
                if advance() != ')':
                    raise PolicyError('paren')
                return (word, path)
        raise PolicyError('pred')

    rules = []
    while pos < n:
        pred = parse_pred(1)
        action = advance()
        if action == 'k:allow':
            act = 'allow'
        elif action == 'k:drop':
            act = 'drop'
        else:
            raise PolicyError('action')
        if advance() != ';':
            raise PolicyError('semi')
        rules.append((pred, act))
    return rules


def parse_policy(text):
    """Parse and bound-check a policy string.

    Returns (rules, atom_occurrences, path_service_occurrences).  Raises
    PolicyError for syntax errors and for violations of the declared bounds.
    """
    rules = _parse(tokenize(text))
    complex_rules = 0
    distinct_nonmatch = set()
    atoms = 0
    path_services = 0
    for pred, _act in rules:
        simple = pred[0] == 'match'
        if not simple:
            complex_rules += 1
        local = 0
        stack = [pred]
        while stack:
            node = stack.pop()
            kind = node[0]
            if kind in _ATOM_KINDS:
                path = node[1]
                atoms += 1
                local += 1
                path_services += len(path)
                if len(path) > 16:
                    raise PolicyError('pathlen')
                if kind != 'match':
                    if len(path) > 4:
                        raise PolicyError('nonmatch-len')
                    distinct_nonmatch.add((kind, path))
            else:
                stack.append(node[1])
                if kind != 'not':
                    stack.append(node[2])
        if not simple and local > 32:
            raise PolicyError('expression')
    if complex_rules > 8:
        raise PolicyError('complex')
    if len(distinct_nonmatch) > 4:
        raise PolicyError('nonmatch')
    if atoms > 32768:
        raise PolicyError('atoms')
    if path_services > 65536:
        raise PolicyError('paths')
    return rules, atoms, path_services
